import Ajv, {type ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  validator?: ValidateFunction;
  validatorsBySchema: WeakMap<object, ValidateFunction>;
}

interface ValidationErrorDetails {
  keyword?: string;
  instancePath?: string;
  dataPath?: string;
  params?: {missingProperty?: string; type?: string};
}

function describeValidationError(error: ValidationErrorDetails | undefined): {property: string; reason: string} {
  const property = validationPropertyPath(error?.instancePath, error?.dataPath);
  if (error?.keyword === 'required') {
    const missingProperty = error.params?.missingProperty;
    return {
      property: requiredPropertyPath(property, missingProperty),
      reason: 'is required',
    };
  }
  if (error?.keyword === 'type') {
    return {
      property,
      reason: `must be of type ${error.params?.type ?? 'the declared schema type'}`,
    };
  }
  if (error?.keyword === 'enum') {
    return {property, reason: 'must satisfy the declared enum'};
  }
  return {
    property,
    reason: `failed ${error?.keyword ?? 'schema validation'}`,
  };
}

function requiredPropertyPath(parent: string, missingProperty: string | undefined): string {
  if (!missingProperty) return parent;
  return [parent === 'input' ? '' : parent, missingProperty].filter(Boolean).join('.');
}

function validationPropertyPath(instancePath: string | undefined, dataPath: string | undefined): string {
  if (instancePath) {
    return instancePath
      .split('/')
      .slice(1)
      .map(segment => segment.replace(/~1/g, '/').replace(/~0/g, '~'))
      .join('.');
  }
  const path = dataPath?.replace(/^\.?/, '').replace(/\[['"]?([^'"\]]+)['"]?\]/g, '.$1');
  return (
    path
      ?.replace(/^input(?:[./]|$)/, '')
      .replace(/^\/+/, '')
      .replace(/\//g, '.') || 'input'
  );
}

function schemaCompilationError(toolName: string, error: unknown): Error {
  const message = error instanceof Error ? error.message : String(error);
  return new Error(`Failed to compile inputSchema for tool '${toolName}': ${message}`);
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly ajv = new Ajv({strict: false, validateFormats: false} as ConstructorParameters<typeof Ajv>[0]);

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    let validator: ValidateFunction | undefined;
    if (typeof definition !== 'function') {
      try {
        validator = this.ajv.compile(resolved.inputSchema);
      } catch (error) {
        throw schemaCompilationError(resolved.name, error);
      }
    }
    this.tools.set(resolved.name, {
      definitionSource: definition,
      execute,
      validator,
      validatorsBySchema: new WeakMap(),
    });
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates tool input and returns schema rejections; only unknown tool names throw (specs/hal-engine-tool-input-validation/spec.md). */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const definition = this.resolveDefinition(tool.definitionSource);
    const validator =
      tool.validator ?? tool.validatorsBySchema.get(definition.inputSchema) ?? this.ajv.compile(definition.inputSchema);
    if (!tool.validator) {
      tool.validatorsBySchema.set(definition.inputSchema, validator);
    }
    if (!validator(input)) {
      const error = validator.errors?.[0] as ValidationErrorDetails | undefined;
      const {property, reason} = describeValidationError(error);
      log.warn('tool', 'input rejected', {name, property, keyword: error?.keyword});
      return {result: `Input validation failed: property '${property}' ${reason}.`};
    }
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}
import {ToolRegistry} from './registry.js';

function exposeLegacyDataPath(registry: ToolRegistry, path: (instancePath: string) => string): void {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
  };
  const originalCompile = ajv.compile.bind(ajv);
  ajv.compile = schema => {
    const validator = originalCompile(schema);
    const legacyValidator = ((input: Record<string, unknown>) => {
      const valid = validator(input);
      if (!valid && validator.errors) {
        const error = validator.errors[0] as {dataPath?: string; instancePath?: string};
        error.dataPath = path(error.instancePath ?? '');
        delete error.instancePath;
      }
      legacyValidator.errors = validator.errors;
      return valid;
    }) as ((input: Record<string, unknown>) => boolean) & {errors?: unknown[]};
    return legacyValidator;
  };
}

function registerWeatherTool(registry: ToolRegistry, executorCalls: {value: number}): void {
  registry.register(
    {
      name: 'get_weather',
      description: 'Get weather for a location',
      inputSchema: {
        type: 'object',
        properties: {location: {type: 'string'}},
        required: ['location'],
      },
    },
    async () => {
      executorCalls.value += 1;
      return 'sunny';
    }
  );
}

function countValidatorCompilations(registry: ToolRegistry): {get: () => number} {
  const ajv = Reflect.get(registry, 'ajv') as {
    compile: (schema: object) => unknown;
  };
  const originalCompile = ajv.compile.bind(ajv);
  let compileCalls = 0;
  ajv.compile = schema => {
    compileCalls += 1;
    return originalCompile(schema);
  };
  return {get: () => compileCalls};
}

describe('ToolRegistry input validation', () => {
  // spec: specs/hal-engine-tool-input-validation#1
  it('returns a rejection for missing required input without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executorCalls = {value: 0};
    registerWeatherTool(registry, executorCalls);

    const response = await registry.execute('get_weather', {});

    expect({
      resultNamesRequiredLocation: /location.*required/i.test(response.result),
      executorCalls: executorCalls.value,
    }).toEqual({resultNamesRequiredLocation: true, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#1
  it('reports a nested missing required property using its full field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_profile_required_name',
        description: 'Look up a profile by name',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {name: {type: 'string'}},
              required: ['name'],
            },
          },
          required: ['profile'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_profile_required_name', {profile: {}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports the expected type for a rejected property without exposing its value', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_record',
        description: 'Look up a record by identifier',
        inputSchema: {
          type: 'object',
          properties: {identifier: {type: 'string'}},
          required: ['identifier'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'found';
      }
    );

    const response = await registry.execute('lookup_record', {identifier: 123456789});

    expect({
      resultNamesFieldAndType: response.result.includes('identifier') && response.result.includes('string'),
      leaksValue: response.result.includes('123456789'),
      executorCalls,
    }).toEqual({resultNamesFieldAndType: true, leaksValue: false, executorCalls: 0});
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a nested rejected property using its field path', async () => {
    const registry = new ToolRegistry();
    registry.register(
      {
        name: 'lookup_profile',
        description: 'Look up a profile',
        inputSchema: {
          type: 'object',
          properties: {
            profile: {
              type: 'object',
              properties: {name: {type: 'string'}},
            },
          },
          required: ['profile'],
        },
      },
      async () => 'found'
    );

    const response = await registry.execute('lookup_profile', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('reports an enum rejection by naming the property and constraint', async () => {
    const registry = new ToolRegistry();
    let executorCalls = 0;
    registry.register(
      {
        name: 'lookup_forecast',
        description: 'Look up a forecast',
        inputSchema: {
          type: 'object',
          properties: {kind: {enum: ['current', 'weekly']}},
          required: ['kind'],
        },
      },
      async () => {
        executorCalls += 1;
        return 'forecast';
      }
    );

    const response = await registry.execute('lookup_forecast', {kind: 'hourly'});

    expect({result: response.result, executorCalls}).toEqual({
      result: "Input validation failed: property 'kind' must satisfy the declared enum.",
      executorCalls: 0,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('reports a rejected property when the validator exposes a legacy data path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => instancePath.replace(/^\//, '.'));
    registry.register(
      () => ({
        name: 'legacy_path',
        description: 'Validate a legacy path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('strips a legacy input root from a rejected property path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_root_path',
        description: 'Validate a legacy root path',
        inputSchema: {type: 'object', properties: {identifier: {type: 'string'}}, required: ['identifier']},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_root_path', {identifier: 123});

    expect(response.result).toContain("property 'identifier'");
  });

  // spec: specs/hal-engine-tool-input-validation#2
  it('normalizes a slash-separated legacy input root in a rejected path', async () => {
    const registry = new ToolRegistry();
    exposeLegacyDataPath(registry, instancePath => `.input${instancePath}`);
    registry.register(
      () => ({
        name: 'legacy_slash_path',
        description: 'Validate a slash-separated legacy path',
        inputSchema: {type: 'object', properties: {profile: {type: 'object', properties: {name: {type: 'string'}}}}},
      }),
      async () => 'found'
    );

    const response = await registry.execute('legacy_slash_path', {profile: {name: 123}});

    expect(response.result).toContain("property 'profile.name'");
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('passes valid input and undeclared properties through unchanged', async () => {
    const registry = new ToolRegistry();
    const input = {location: 'Paris', units: 'metric'};
    let received: Record<string, unknown> | undefined;
    registry.register(
      {
        name: 'passthrough_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async toolInput => {
        received = toolInput;
        return {result: 'sunny'};
      }
    );

    const response = await registry.execute('passthrough_weather', input);

    expect({received, response}).toEqual({received: input, response: {result: 'sunny'}});
  });

  // spec: specs/hal-engine-tool-input-validation#3
  it('names the tool when a static schema cannot be compiled', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_static_schema',
          description: 'Has an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {location: {type: 'not-a-json-schema-type'}},
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_static_schema/);
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('caches a function-valued schema validator by object reference', async () => {
    const registry = new ToolRegistry();
    const compilation = countValidatorCompilations(registry);
    const schema = {
      type: 'object',
      properties: {location: {type: 'string'}},
      required: ['location'],
    };
    let executorCalls = 0;
    registry.register(
      () => ({
        name: 'cached_weather',
        description: 'Get weather for a location',
        inputSchema: schema,
      }),
      async () => {
        executorCalls += 1;
        return 'sunny';
      }
    );

    await registry.execute('cached_weather', {location: 'Paris'});
    schema.required = ['city'];
    const response = await registry.execute('cached_weather', {location: 'Paris'});

    expect({compileCalls: compilation.get(), result: response.result, executorCalls}).toEqual({
      compileCalls: 1,
      result: 'sunny',
      executorCalls: 2,
    });
  });

  // spec: specs/hal-engine-tool-input-validation#6
  it('compiles a static schema once at registration and reuses it across executions', async () => {
    const registry = new ToolRegistry();
    const compilation = countValidatorCompilations(registry);
    registry.register(
      {
        name: 'static_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      async input => JSON.stringify(input)
    );

    const results = await Promise.all(
      Array.from({length: 10}, () => registry.execute('static_weather', {location: 'Paris'}))
    );

    expect({compileCalls: compilation.get(), resultCount: results.length}).toEqual({compileCalls: 1, resultCount: 10});
  });
});

